"""Rate-limited concurrent poller — reference solution."""
import asyncio
import time
from typing import Awaitable, Callable, Iterable


class RetryableError(Exception):
    pass


class PermanentError(Exception):
    pass


_MAX_CONCURRENCY = 8
_RATE_PER_SEC = 10
_BACKOFFS = [0.5, 1.0, 2.0]


class _TokenBucket:
    def __init__(self, rate_per_sec: int):
        self._capacity = rate_per_sec
        self._tokens = rate_per_sec
        self._rate = rate_per_sec
        self._lock = asyncio.Lock()
        self._last = time.monotonic()

    async def acquire(self):
        async with self._lock:
            while True:
                now = time.monotonic()
                elapsed = now - self._last
                self._tokens = min(self._capacity, self._tokens + elapsed * self._rate)
                self._last = now
                if self._tokens >= 1:
                    self._tokens -= 1
                    return
                wait = (1 - self._tokens) / self._rate
                await asyncio.sleep(wait)


async def _one(id_, fetch_one, sem, bucket):
    async with sem:
        for attempt in range(len(_BACKOFFS) + 1):
            await bucket.acquire()
            try:
                data = await fetch_one(id_)
                return id_, {'ok': True, 'data': data}
            except PermanentError as e:
                return id_, {'error': str(e)}
            except RetryableError as e:
                if attempt >= len(_BACKOFFS):
                    return id_, {'error': f'retries_exhausted: {e}'}
                await asyncio.sleep(_BACKOFFS[attempt])


async def poll_all(ids, fetch_one):
    sem = asyncio.Semaphore(_MAX_CONCURRENCY)
    bucket = _TokenBucket(_RATE_PER_SEC)
    tasks = [asyncio.create_task(_one(i, fetch_one, sem, bucket)) for i in ids]
    results = {}
    for t in asyncio.as_completed(tasks):
        id_, r = await t
        results[id_] = r
    return results
